:root {
  --ink: #24322b;
  --paper: #fffdf5;
  --accent: #d96d3b;
}

.pass {
  width: 460px;
  overflow: hidden;
  border: 2px solid var(--ink);
  border-radius: 14px;
  background: var(--paper);
}

.pass-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  background: var(--accent);
  color: var(--paper);
}

.mark {
  font-size: 22px;
  line-height: 1;
}

.pass h1 {
  flex: 1;
  margin: 0;
  font-size: 20px;
  line-height: 1;
}

.admit {
  padding: 4px 7px;
  border: 1px solid var(--paper);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
}

.details {
  display: flex;
  justify-content: space-between;
  padding: 16px;
  color: var(--ink);
  font-size: 14px;
}

.pass-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 2px dashed var(--ink);
  color: var(--ink);
  font-size: 12px;
}

button {
  padding: 6px 10px;
  border: 0;
  border-radius: 6px;
  background: var(--ink);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}
